import { StrictMode, useRef, useState } from 'react';
import { createRoot } from 'react-dom/client';
import { createPortal } from 'react-dom';
import { CreatorButton, CreatorSlider } from '../../src/components/creator-controls';
import { CREATOR_CONTROLS } from '../../src/game/core/creator-controls';
import { CREATOR_PALETTE } from '../../src/game/core/creator-palette';
import {
  ENEMY_STAT_LIMITS,
  NEW_ENEMY_STATS,
  enemyStatHandle,
  enemyStatFromHandle,
  type EnemyStat,
} from '../../src/game/core/creator-enemy-stats';
import type { AssetPack } from '../../src/game/assets/asset-pack';

function ControlsFixture({
  pack,
  host,
  controlsHost,
}: {
  pack: AssetPack;
  host: HTMLElement;
  controlsHost: HTMLElement;
}) {
  const [checked, setChecked] = useState(true),
    [undo, setUndo] = useState(false),
    [scale, setScale] = useState(1),
    [rotation, setRotation] = useState(0),
    [resetKey, setResetKey] = useState({}),
    [enemy, setEnemy] = useState(NEW_ENEMY_STATS),
    [enemyDisabled, setEnemyDisabled] = useState(false),
    [enemyReset, setEnemyReset] = useState(0),
    [x, setX] = useState(0);
  const held = useRef(0),
    beforeEnemy = useRef(enemy),
    before = useRef(1);
  const report = (name: string, value: unknown) => {
    host.dataset[name] = JSON.stringify(value);
  };
  const record = (name: string) => report(name, Number(host.dataset[name] ?? '0') + 1);
  const labels: Record<string, string> = {
    SymmetricMode_mc: 'Symmetric Mode',
    LoadTank_mc: 'Load tank',
    SaveExit_mc: 'Save and exit',
    Exit_mc: 'Exit tank creator',
    DeleteButton_mc: 'Delete selected',
    BringFront_mc: 'Bring to front',
    SendBack_mc: 'Send to back',
    AlignCenter_mc: 'Align to center',
    Undo_mc: 'Undo',
    Left_mc: 'Nudge left',
    Right_mc: 'Nudge right',
  };
  return (
    <>
      <div className="creator stage-background" data-assets={pack.mode}>
        {CREATOR_CONTROLS.controls.map((c) => {
          const direction = c.name === 'Left_mc' ? -1 : c.name === 'Right_mc' ? 1 : 0;
          return (
            <CreatorButton
              key={c.name}
              pack={pack}
              name={c.name}
              label={labels[c.name]}
              checked={c.name === 'SymmetricMode_mc' ? checked : undefined}
              disabled={c.name === 'Undo_mc' && !undo}
              onClick={() => {
                if (c.name === 'SymmetricMode_mc') setChecked((v) => !v);
                if (direction) setX((v) => v + direction);
                record('controlClicks');
              }}
              onHoldStart={
                direction
                  ? () => {
                      held.current = direction;
                      record('holdStarts');
                    }
                  : undefined
              }
              onHoldEnd={
                direction
                  ? (click) => {
                      held.current = 0;
                      if (click) setX((v) => v + direction);
                      record('holdEnds');
                      report('holdClick', click);
                    }
                  : undefined
              }
            />
          );
        })}
        {CREATOR_CONTROLS.sliders.map((layout) => {
          const resize = layout.name === 'Resize_mc';
          return (
            <CreatorSlider
              key={layout.name}
              pack={pack}
              layout={layout}
              label={resize ? 'Part scale' : 'Part rotation'}
              value={resize ? scale : rotation}
              resetKey={resetKey}
              min={resize ? 0.5 : 0}
              max={resize ? 2 : 360}
              onBegin={() => {
                before.current = resize ? scale : rotation;
                record('sliderBegins');
              }}
              onChange={(v) => {
                if (resize) setScale(v);
                else setRotation(v);
                record('sliderChanges');
              }}
              onEnd={(cancel) => {
                if (cancel) {
                  if (resize) setScale(before.current);
                  else setRotation(before.current);
                }
                record('sliderEnds');
                report('sliderCancel', cancel);
              }}
            />
          );
        })}
        {CREATOR_PALETTE.advanced.sliders.map((layout, index) => {
          const key: EnemyStat = (['life', 'reward', 'speed'] as const)[index];
          return (
            <CreatorSlider
              key={layout.name}
              pack={pack}
              layout={layout}
              label={`Fixture enemy ${key}`}
              value={enemy[key]}
              resetKey={enemyReset}
              disabled={enemyDisabled}
              {...ENEMY_STAT_LIMITS[key]}
              coordinates={{
                min: -55,
                max: 55,
                toX: (v) => enemyStatHandle(key, v),
                fromX: (v) => enemyStatFromHandle(key, v),
              }}
              onBegin={() => {
                beforeEnemy.current = enemy;
                record('enemyBegins');
              }}
              onChange={(v) => setEnemy((current) => ({ ...current, [key]: v }))}
              onEnd={(cancel) => {
                if (cancel) setEnemy(beforeEnemy.current);
                report('enemyCancel', cancel);
                record('enemyEnds');
              }}
            />
          );
        })}
        <span className="sr-only" data-control-values>
          {JSON.stringify({ checked, scale, rotation, x, enemy })}
        </span>
      </div>
      {createPortal(
        <div>
          <button onClick={() => setEnemyDisabled((value) => !value)}>
            Toggle fixture enemy disabled
          </button>
          <button
            onClick={() => {
              setEnemy(NEW_ENEMY_STATS);
              setEnemyReset((value) => value + 1);
            }}
          >
            Reset fixture enemy
          </button>
          <button onClick={() => setUndo((v) => !v)}>Toggle fixture undo</button>
          <button
            onClick={() => {
              setScale(3);
              setResetKey({});
            }}
          >
            Load fixture scale 3
          </button>
          <button
            onClick={() => {
              setScale(1);
              setRotation(0);
              setResetKey({});
            }}
          >
            Reset fixture selection
          </button>
          <button onClick={() => setX((v) => v + held.current * 3)}>
            Step fixture hold 3 frames
          </button>
        </div>,
        controlsHost,
      )}
    </>
  );
}
export function showCreatorControls(pack: AssetPack, host: HTMLElement) {
  for (const name of [
    'controlClicks',
    'holdStarts',
    'holdEnds',
    'sliderBegins',
    'sliderChanges',
    'sliderEnds',
  ])
    host.dataset[name] = '0';
  const controlsHost = document.createElement('div');
  controlsHost.id = 'creator-component-fixture-controls';
  host.before(controlsHost);
  const root = createRoot(host);
  root.render(
    <StrictMode>
      <ControlsFixture pack={pack} host={host} controlsHost={controlsHost} />
    </StrictMode>,
  );
  return () => {
    root.unmount();
    controlsHost.remove();
  };
}

import { svgMaskDefinition } from '../../src/game/assets/svg-mask';
import { AssetPack } from '../../src/game/assets/asset-pack';

/** The real compiler must retain nested group transforms, holes and alpha-zero mask fills. */
async function composedMask() {
  const pack = new AssetPack('swf');
  const matrix = (x = 0, y = 0) => ({ a: 1, b: 0, c: 0, d: 1, tx: x * 20, ty: y * 20 });
  Object.assign(pack, {
    shapes: new Map(
      [96001, 96002].map((id) => [
        id,
        {
          id,
          bounds: { xMin: 0, yMin: 0, xMax: 2000, yMax: 2000 },
        },
      ]),
    ),
    symbols: {
      svgByCid: new Map([
        [96001, '<svg><rect width="100" height="100" fill="red"/></svg>'],
        [
          96002,
          '<svg><path fill="blue" fill-opacity="0" fill-rule="evenodd" d="M0 0H40V40H0Z M10 10H30V30H10Z"/></svg>',
        ],
      ]),
    },
    sprites: new Map([
      [
        96003,
        {
          id: 96003,
          frameCount: 1,
          placements: [
            {
              frame: 1,
              depth: 1,
              charId: 96002,
              matrix: matrix(10, 20),
              color: { mult: [1, 1, 1, 0], add: [0, 0, 0, 0] },
            },
          ],
        },
      ],
      [
        96000,
        {
          id: 96000,
          frameCount: 1,
          placements: [
            { frame: 1, depth: 1, charId: 96003, matrix: matrix(20, 0), clipDepth: 2 },
            { frame: 1, depth: 2, charId: 96001 },
          ],
        },
      ],
    ]),
  });
  try {
    const raster = await pack.rasterSymbol(96000);
    if (!raster) throw new Error('Missing synthetic compound mask raster');
    const pixel = (x: number, y: number) =>
      Array.from(
        raster.canvas
          .getContext('2d')!
          .getImageData(
            Math.floor((x - raster.x) * raster.resolution),
            Math.floor((y - raster.y) * raster.resolution),
            1,
            1,
          ).data,
      );
    return { visible: pixel(35, 25), hole: pixel(45, 35), outside: pixel(75, 25) };
  } finally {
    pack.dispose();
  }
}

/** Pixel evidence for the production SVG composer, independent of Pixi masks. */
export async function showSvgMasks(pack: AssetPack, host: HTMLElement) {
  const canvas = document.createElement('canvas');
  canvas.width = 550;
  canvas.height = 450;
  host.append(canvas);
  const context = canvas.getContext('2d')!;
  const bounds = { x: 0, y: 0, width: 100, height: 100 };
  const inner = svgMaskDefinition(
    'inner',
    '<g transform="translate(10 0)"><rect width="10" height="100"/></g>',
    bounds,
  );
  const cases = [
    [
      'transformed',
      '<g transform="translate(10 20)"><g transform="scale(2)"><rect width="10" height="10"/></g></g>',
    ],
    [
      'transparent-fill',
      '<g opacity="0" filter="url(#absent)"><path fill="red" fill-opacity="0" d="M10 10H30V30H10Z"/></g>',
    ],
    ['stroke-only', '<path fill="none" stroke="red" stroke-width="20" d="M10 10H30V30H10Z"/>'],
    ['hole', '<path fill="red" fill-rule="evenodd" d="M10 10H80V80H10Z M30 30H60V60H30Z"/>'],
    [
      'nested',
      `<defs>${inner}</defs><g transform="translate(20 0)"><g mask="url(#inner)"><rect width="80" height="80"/></g></g>`,
    ],
  ];
  const proof: Record<string, { visible: number[]; outside: number[] }> = {};
  const probes = [
    [15, 25, 35, 25],
    [15, 15, 35, 15],
    [15, 15, 5, 15],
    [15, 15, 40, 40],
    [35, 15, 25, 15],
  ];
  for (const [index, [name, body]] of cases.entries()) {
    const image = new Image();
    const mask = svgMaskDefinition('outer', body, bounds);
    image.src =
      'data:image/svg+xml,' +
      encodeURIComponent(
        `<svg xmlns="http://www.w3.org/2000/svg" width="100" height="100"><defs>${mask}</defs><rect width="100" height="100" fill="red" mask="url(#outer)"/></svg>`,
      );
    await image.decode();
    const x = index * 105;
    context.drawImage(image, x, 0);
    const [px, py, ox, oy] = probes[index];
    proof[name] = {
      visible: Array.from(context.getImageData(x + px, py, 1, 1).data),
      outside: Array.from(context.getImageData(x + ox, oy, 1, 1).data),
    };
  }

